use winit::window::Icon;

/// Generated by `scripts/gen-icons.sh` from `packaging/icon/emu-rust.svg` (ADR 0023 §2); never copied into this crate.
static ICON_256: &[u8] = include_bytes!("../../../packaging/icon/png/256.png");

/// Window icon (`packaging/icon/png/256.png`); `None` (logged) when it cannot be decoded. macOS ignores it (bundle
/// icon); Wayland has no window icon (the `.desktop` file applies).
pub fn window_icon() -> Option<Icon> {
    match decode(ICON_256) {
        Ok(icon) => Some(icon),
        Err(e) => {
            tracing::warn!("icône de fenêtre indisponible : {e}");
            None
        }
    }
}

/// PNG (any bit depth, RGB or RGBA, grey) to a winit icon.
fn decode(bytes: &[u8]) -> Result<Icon, String> {
    let mut decoder = png::Decoder::new(std::io::Cursor::new(bytes));
    decoder.set_transformations(png::Transformations::normalize_to_color8());
    let mut reader = decoder.read_info().map_err(|e| e.to_string())?;
    let mut buf = vec![0; reader.output_buffer_size().ok_or("image trop grande")?];
    let info = reader.next_frame(&mut buf).map_err(|e| e.to_string())?;
    let data = &buf[..info.buffer_size()];
    let rgba: Vec<u8> = match info.color_type {
        png::ColorType::Rgba => data.to_vec(),
        png::ColorType::Rgb => data
            .as_chunks::<3>()
            .0
            .iter()
            .flat_map(|p| [p[0], p[1], p[2], 255])
            .collect(),
        png::ColorType::GrayscaleAlpha => data
            .as_chunks::<2>()
            .0
            .iter()
            .flat_map(|p| [p[0], p[0], p[0], p[1]])
            .collect(),
        png::ColorType::Grayscale => data.iter().flat_map(|&g| [g, g, g, 255]).collect(),
        png::ColorType::Indexed => return Err("PNG indexé non pris en charge".to_owned()),
    };
    Icon::from_rgba(rgba, info.width, info.height).map_err(|e| e.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_icon_decodes() {
        assert!(window_icon().is_some());
        assert!(decode(b"not a png").is_err());
    }
}
